H.background();
// Ideal gas law:  P*V = n*R*T   ->   P = n*R*T / V
// A piston holds n moles at temperature T; the volume breathes in and out, and
// the pressure responds inversely. Particles bounce inside, faster when hot.
const w = H.W, h = H.H;
const R = 8.314;       // gas constant J/(mol*K)
const n = P.n;         // moles
const T = P.T;         // temperature in kelvin
const Vset = P.V;      // baseline volume in liters
// Volume oscillates around the slider value (piston breathing), bounded > 0.
const V = Math.max(0.2, Vset * (1 + 0.35 * Math.sin(t * 0.9)));  // liters
const Vm3 = V / 1000;                       // liters -> m^3
const Pp = (Vm3 > 1e-9) ? n * R * T / Vm3 : 0; // pressure in pascals
const Pkpa = Pp / 1000;                     // kPa for readout
H.text("Ideal gas law:  P·V = n·R·T", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n = " + n.toFixed(2) + " mol    T = " + T.toFixed(0) + " K    V = " + V.toFixed(2) + " L    R = 8.314 J/(mol·K)", 24, 52, { color: H.colors.sub, size: 12 });
// Cylinder
const cx = 110, cyTop = 100, cw = 230, cyBot = h - 70;
// piston height maps from current volume (more volume -> piston higher up)
const fullH = cyBot - cyTop;
const fillFrac = H.clamp(V / (Vset * 1.5), 0.12, 1);
const pistonY = cyBot - fillFrac * fullH;
// cylinder walls
H.line(cx, cyTop - 10, cx, cyBot, { color: H.colors.axis, width: 2 });
H.line(cx + cw, cyTop - 10, cx + cw, cyBot, { color: H.colors.axis, width: 2 });
H.line(cx, cyBot, cx + cw, cyBot, { color: H.colors.axis, width: 2 });
// gas region tint by temperature (cool->hot)
const heat = H.clamp((T - 200) / 500, 0, 1);
H.rect(cx + 2, pistonY, cw - 4, cyBot - pistonY, { fill: H.hsl(220 - 200 * heat, 60, 28) });
// piston plate + rod
H.rect(cx - 6, pistonY - 14, cw + 12, 14, { fill: H.colors.sub, radius: 3 });
H.rect(cx + cw / 2 - 6, pistonY - 54, 12, 40, { fill: H.colors.axis });
// downward force arrows on the piston (pressure pushing back)
H.arrow(cx + cw / 2, pistonY - 70, cx + cw / 2, pistonY - 18, { color: H.colors.warn, width: 3, head: 9 });
// gas particles: bounce inside the gas box, speed scales with sqrt(T)
const speed = 0.4 + Math.sqrt(T) / 30;
const np = 14;
for (let i = 0; i < np; i++) {
  const sx = 0.13 + 0.74 * (((i * 0.6180339) % 1));     // seed x in [0.13,0.87]
  const sy = ((i * 0.41421) % 1);
  // triangle-wave bounce keeps each particle inside the box and looping
  const px = cx + 14 + (cw - 28) * (0.5 + 0.5 * Math.sin(t * speed * (1 + i * 0.05) + i));
  const boxH = cyBot - pistonY - 16;
  const py = (pistonY + 12) + Math.abs(((sy + t * speed * 0.7) % 2) - 1) * Math.max(6, boxH);
  H.circle(px, py, 3.5, { fill: H.colors.accent });
}
// pressure gauge (right): needle angle from pressure
const gx = w - 130, gy = 180, gr = 64;
H.circle(gx, gy, gr, { stroke: H.colors.axis, width: 2 });
const pFrac = H.clamp(Pkpa / 5000, 0, 1);
const ang = Math.PI * (1 - pFrac); // needle sweeps 180deg (left) at 0 -> 0deg (right) at max
H.arrow(gx, gy, gx + gr * 0.8 * Math.cos(ang), gy - gr * 0.8 * Math.sin(ang), { color: H.colors.warn, width: 3, head: 8 });
H.text("P", gx - 4, gy + gr + 18, { color: H.colors.sub, size: 13 });
// readouts
H.text("P = " + Pkpa.toFixed(1) + " kPa", w - 200, 52, { color: H.colors.good, size: 15, weight: 700 });
H.text("V = " + V.toFixed(2) + " L", w - 200, 74, { color: H.colors.accent, size: 13 });
H.text("P↑ when V↓  (T, n fixed)", gx - 90, gy + gr + 40, { color: H.colors.sub, size: 11 });
